#!/usr/bin/env node
import { readConfig, updateConfig } from "./lib/secrets/secretStore.mjs";
import { spawn, spawnSync } from "node:child_process";
import { validateConnection as checkConnection } from "./lib/daemon/connection.mjs";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { configureAgents, AGENTS } from "./lib/agents/adapters.mjs";
import { wiringOf } from "./lib/agents/agentWiring.mjs";
import {
  addAgents,
  banner,
  removeAgent,
  showLineup,
  setupSwarm,
  testAgent,
} from "./lib/daemon/onboard.mjs";
import { agentsHere, createLineup } from "./lib/swarm/lineup.mjs";
import { confirmAgentBinary } from "./lib/agents/agentBinaries.mjs";
import { createUi, stopSpinner } from "./lib/daemon/ui.mjs";
import { backupCommand } from "./lib/daemon/backupSetup.mjs";
import pc from "picocolors";
import {
  chosenAgents,
  removeHarnessHere,
} from "./lib/daemon/removeHarness.mjs";
import { detectAgents } from "./lib/agents/commands.mjs";
import { PROPOSERS, nameOf } from "./lib/swarm/members.mjs";
import {
  describeDispatcher,
  dispatcherNotReady,
} from "./lib/swarm/dispatcher.mjs";
import { modelsWanted } from "./lib/models/coreModels.mjs";
import { daemonRequest } from "./lib/daemon/control-client.mjs";
import { ensureDir, readJson } from "./lib/daemon/files.mjs";
import { hostApp, processTable } from "./lib/agents/live.mjs";
import { noteSetupTerminal } from "./lib/agents/places.mjs";
import { readScreenFacts, whereSetupShows } from "./lib/daemon/screen.mjs";
import { harnessNode, paths } from "./lib/daemon/paths.mjs";
import { cloudEnroll } from "./lib/devices/cloudBoot.mjs";
import { ownPublicKey, sshCommand } from "./lib/devices/cloudSsh.mjs";
import { viewSession } from "./lib/devices/sessionViewer.mjs";
import {
  checkRuntime,
  currentRuntime,
  fetchRelease,
  installRuntime,
  relayCommand,
  updateHarnessNode,
} from "./lib/daemon/runtime-install.mjs";
import { installNativeHost } from "./lib/devices/nativeHost.mjs";
import { awayWords } from "./lib/devices/quietComputers.mjs";
import { MODELS, modelsPresent } from "./lib/models/localmodels.mjs";
import {
  installService,
  launcherMissing,
  serviceInfo,
  serviceRunning,
  uninstallService,
} from "./lib/daemon/service.mjs";
import {
  canShowDesktop,
  desktopInstalled,
  openDesktop,
  setupDesktop,
} from "./lib/daemon/desktop.mjs";

const SOURCE_ROOT = path.dirname(fileURLToPath(import.meta.url));
const PACKAGE = readJson(path.join(SOURCE_ROOT, "package.json"), {
  version: "0.4.3",
});
const VERSION = PACKAGE.version;
const NODE_MAJOR = Number(process.versions.node.split(".")[0]);
if (!Number.isFinite(NODE_MAJOR) || NODE_MAJOR < 18) {
  console.error(
    `tryharness requires Node.js 18 or newer (current: ${process.version}). Upgrade Node, then rerun: npx tryharness`
  );
  process.exit(1);
}
const argv = process.argv.slice(2);
const command = ["--help", "-h"].includes(argv[0])
  ? (argv.shift(), "help")
  : argv[0] === "--version"
    ? (argv.shift(), "version")
    : argv[0] && !argv[0].startsWith("-")
      ? argv.shift()
      : "connect";

function arg(flag, fallback = null) {
  const index = argv.indexOf(flag);
  return index >= 0 && argv[index + 1] ? argv[index + 1] : fallback;
}
function has(flag) {
  return argv.includes(flag);
}
function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}
function shellQuote(value) {
  return `'${String(value).replace(/'/g, `'\\''`)}'`;
}
function resumeCommand(agent, sessionId, cwd) {
  const command =
    agent === "claude-code"
      ? `claude --dangerously-skip-permissions --resume ${shellQuote(sessionId)}`
      : agent === "codex"
        ? `codex resume --dangerously-bypass-approvals-and-sandbox ${shellQuote(sessionId)}`
        : agent === "pi"
          ? `pi --approve --session ${shellQuote(sessionId)}`
          : `opencode --auto --session ${shellQuote(sessionId)}`;
  return cwd ? `cd ${shellQuote(cwd)} && ${command}` : command;
}
function origin() {
  const saved = readConfig(paths.config, {});
  return String(
    arg("--origin", saved.origin || "https://tryharness.ai")
  ).replace(/\/$/, "");
}

async function waitForDaemon(timeoutMs = 12_000) {
  const deadline = Date.now() + timeoutMs;
  let lastError;
  let lastStatus;
  while (Date.now() < deadline) {
    try {
      lastStatus = await daemonRequest({ command: "status" }, 1_000);
      if (lastStatus.connected) return lastStatus;
      const why = lastStatus.heldElsewhere || lastStatus.lastError;
      if (why) lastError = new Error(why);
    } catch (error) {
      lastError = error;
    }
    await new Promise((resolve) => setTimeout(resolve, 250));
  }
  throw new Error(
    `daemon started but its authenticated Harness bridge did not become ready: ${lastError?.message || lastStatus?.lastError || "timeout"}. Run: ${relayCommand()} doctor`
  );
}

// While this computer is not signed in, its daemon holds a sign-in open (setupMode.mjs): wait for it to answer with
// the code and link, or for it to be signed in already (another computer took the code first).
async function setupState(timeoutMs = 12_000) {
  const deadline = Date.now() + timeoutMs;
  let last;
  while (Date.now() < deadline) {
    try {
      const state = await daemonRequest({ command: "setup.state" }, 1_000);
      if (state.ok && (state.code || state.url)) return state;
      if (state.code === "unknown command" || state.error === "unknown command")
        return null;
      last = state.error;
    } catch (error) {
      last = error.message;
    }
    await new Promise((resolve) => setTimeout(resolve, 250));
  }
  throw new Error(
    `Harness started but could not hold a sign-in: ${last || "no answer"}. Run: ${relayCommand()} doctor`
  );
}

// Signed in on the screen or with the code on another computer, whichever came first; or setup stopped from the
// Harness app (Remove Harness), which takes the background service with it. `onCode` hears the code to compare each
// time a device starts approving this computer (setupMode.mjs).
async function untilSignedIn(onCode = () => {}) {
  let shownCode = null;
  for (;;) {
    const status = await daemonRequest({ command: "status" }, 1_000).catch(
      () => null
    );
    if (status && !status.setup) return "signed in";
    if (status?.setup) {
      const state = await daemonRequest(
        { command: "setup.state" },
        1_000
      ).catch(() => null);
      const code = state?.approvalCode ?? null;
      if (code && code !== shownCode) onCode(code);
      shownCode = code;
    }
    // While setup hands over to the daemon proper, nothing answers for a moment. On a computer with no service file to
    // look at (no systemd) that read as the person stopping setup, and told them Harness was off a computer it runs on.
    if (!status && readConfig(paths.config, {}).token) return "signed in";
    if (!status && !serviceRunning()) return "stopped";
    await new Promise((resolve) => setTimeout(resolve, 1_000));
  }
}

// Backing out before signing in (Ctrl-C) takes back everything setup added, so nothing is left running. Ctrl-C comes as
// a signal, or, while clack's spinner holds the terminal, as a key clack answers by exiting with code 0 (seen
// November 3: the spinner said "Canceled" and the app stayed): both end here. A failed setup exits with an error code
// and keeps what it made, for doctor to look at.
function stopSetupOnCtrlC() {
  let stopped = false;
  const takeBack = () => {
    if (stopped) return;
    stopped = true;
    const { folderRemoved } = removeHarnessHere({
      paths,
      agents: chosenAgents(paths),
      stopService: true,
    });
    const line = stoppedLine(folderRemoved);
    if (!stopSpinner(line)) console.log(`\n${line}`);
  };
  const onSignal = () => {
    takeBack();
    process.exit(130);
  };
  const onExit = (code) => {
    if (code === 0 && !process.exitCode) takeBack();
  };
  process.on("SIGINT", onSignal);
  process.on("exit", onExit);
  return () => {
    process.removeListener("SIGINT", onSignal);
    process.removeListener("exit", onExit);
  };
}

const stoppedLine = (folderRemoved) =>
  folderRemoved
    ? "Setup stopped. Nothing from Harness is left on this computer."
    : `Setup stopped. Harness is off this computer; your board and history from before are kept in ${paths.home.replace(os.homedir(), "~")}.`;

async function connect() {
  ensureDir(paths.home);
  // A release this computer's Harness would refuse is refused before anything else changes.
  checkRuntime({
    sourceRoot: SOURCE_ROOT,
    version: VERSION,
    allowUnsigned: has("--local-build"),
    allowOlder: has("--older"),
  });
  // Setup asks nothing here: signing in, agents, folders and where threads open are chosen on this computer's screen
  // in the Harness app, or from another computer's when this one has none (screen.mjs).
  const found = agentsHere()
    .filter((entry) => AGENTS.includes(entry.id))
    .map((entry) => entry.id);
  const ui = createUi();
  // Where the person works, for Open until it has seen their sessions (places.mjs).
  const table = processTable();
  noteSetupTerminal({
    host: hostApp(table, process.pid),
    tty: table.get(process.pid)?.tty ?? null,
  });
  console.log(`\n${banner(VERSION)}\n`);
  ui.intro(
    `${pc.bgCyan(pc.black(" tryharness "))}  Setting up Harness on this computer`
  );

  const pairOrigin = origin();
  let config = readConfig(paths.config, {});
  const connection =
    !has("--reconnect") && config.origin === pairOrigin && config.token
      ? await checkConnection(config, { version: VERSION })
      : "rejected";
  if (connection === "unreachable")
    ui.warn(
      `Harness did not answer just now, so this computer keeps its connection ${pc.dim(`· ${new URL(pairOrigin).host}`)}. If it really stopped working: ${relayCommand()} --reconnect`
    );
  const signedIn = connection !== "rejected";
  // Not signed in: the daemon starts without a token and holds a sign-in open for the screen or the code.
  const endCtrlCStop = signedIn ? () => {} : stopSetupOnCtrlC();
  if (!signedIn) {
    // Read again as it is written: an unreadable config.json stops setup instead of being replaced.
    updateConfig(paths.config, (current) => {
      const { token: _dropped, ...rest } = current;
      config = { ...rest, origin: pairOrigin };
      return config;
    });
  }

  // The persistent runtime is version-pinned, so the agents the person already chose are pointed at this release; a
  // first setup has none, and the person turns each one on in the Harness app (the daemon's swarm.add).
  const spin = ui.spinner();
  spin.start("Starting Harness on this computer");
  const runtimeRoot = installRuntime({
    sourceRoot: SOURCE_ROOT,
    version: VERSION,
    allowUnsigned: has("--local-build"),
  });
  const chosen = (config.swarmAgents ?? []).filter(
    (agent) => AGENTS.includes(agent) && found.includes(agent)
  );
  const states = configureAgents({ runtimeRoot, selected: chosen });
  for (const agent of chosen) confirmAgentBinary(agent);
  updateConfig(paths.config, (current) => {
    config = {
      ...current,
      version: VERSION,
      runtimeRoot,
      ...modelsWanted(config),
      agentStates: {
        ...config.agentStates,
        ...Object.fromEntries(states.map((state) => [state.agent, state])),
      },
      agentWiring: {
        ...config.agentWiring,
        ...wiringOf(states, runtimeRoot),
      },
      swarmAgents: config.swarmAgents ?? [],
    };
    return config;
  });
  // The app goes in before the background service, so the service starts through the app's launcher from the first:
  // started by Node, macOS announced it as "Software from Node.js Foundation" (seen November 3).
  const where = whereSetupShows(readScreenFacts({ table }));
  const onScreen = where.show === "screen" && !has("--no-desktop");
  if (!signedIn && onScreen)
    await setupDesktop({ sourceRoot: SOURCE_ROOT }).catch(() => null);
  const service = installService({ runtimeRoot });
  const notAtBoot = notAtBootWarning(service);
  if (notAtBoot) ui.warn(notAtBoot);
  // The Harness extension in this computer's browsers hears this daemon by itself, so it can open a Harness page
  // for work that waits on one.
  try {
    installNativeHost({ runtimeRoot });
  } catch (error) {
    ui.warn(
      `The Harness extension cannot hear this computer by itself (${error.message}). Your browsers still reach it once they are on your device list.`
    );
  }
  // Only the agents the person chose are set up here; the rest wait for the Harness app, so they are not failures.
  const failed = states.filter(
    (state) =>
      chosen.includes(state.agent) && state.installed && !state.configured
  );
  if (failed.length) {
    spin.stop("Harness could not set up every agent", 2);
    throw new Error(
      `setup is incomplete for ${failed.map((state) => state.agent).join(", ")}. Nothing was hidden; run ${relayCommand()} doctor after fixing the reported CLI error, then rerun setup.`
    );
  }

  // A cloud computer's service starts the daemon again on this release (installService), and ends this setup with the
  // old one when it does: nothing here is left to wait for.
  if (signedIn && service.manager === "harness-cloud") {
    spin.stop(
      "Harness restarts on this release through this computer's service"
    );
    ui.outro("Done.");
    return;
  }
  if (signedIn) {
    try {
      await waitForDaemon();
    } catch (error) {
      spin.stop("Harness did not connect", 2);
      throw error;
    }
    spin.stop(
      `Harness is running on this computer ${pc.dim(`· ${service.manager}`)}`
    );
    // An upgrade keeps an installed app on the same release.
    if (!has("--no-desktop") && desktopInstalled())
      await showApp(ui, runtimeRoot);
    ui.outro("Done.");
    return;
  }

  const state = await setupState().catch((error) => {
    spin.stop("Harness did not start", 2);
    throw error;
  });
  spin.stop(
    `Harness is running on this computer ${pc.dim(`· ${service.manager}`)}`
  );
  const shown = onScreen ? await showApp(ui, runtimeRoot) : { ok: false };
  const code = state.code ? pc.bold(state.code) : null;
  const otherComputer = code
    ? `type ${code} into Add a Computer in Harness on a computer that already has it`
    : null;
  // With the app open, its sign-in screen shows the code; the terminal keeps it only when no window could open.
  if (shown.ok)
    ui.note(
      [
        "Harness opened on this computer's screen. Sign in there to finish setup.",
        pc.dim(
          "Not at this computer? Open this link in any browser to sign in:"
        ),
        state.url,
      ].join("\n"),
      "Sign in"
    );
  else
    ui.note(
      [
        `Open this link in any browser to sign in${otherComputer ? `, or ${otherComputer}` : ""}:`,
        state.url,
        ...(where.show === "code-first"
          ? [
              pc.dim(
                `To set up on this computer's screen instead: ${relayCommand()} --screen`
              ),
            ]
          : []),
      ].join("\n"),
      "Sign in"
    );
  const waiting = ui.spinner();
  waiting.start("Waiting for you to sign in");
  const ended = await untilSignedIn((approvalCode) =>
    waiting.message(
      `Connect this computer only if your browser shows ${pc.bold(approvalCode)}`
    )
  );
  endCtrlCStop();
  if (ended === "stopped") {
    waiting.stop("Setup stopped in the Harness app");
    ui.outro(stoppedLine(!fs.existsSync(paths.home)));
    return;
  }
  try {
    await waitForDaemon();
  } catch (error) {
    waiting.stop("Signed in, but Harness did not connect", 2);
    throw error;
  }
  waiting.stop("Signed in");
  // The phone's way in comes last (owner, November 23): the code it scans is one press away in the app, or one
  // command here.
  ui.outro(
    shown.ok
      ? "Finish setup on this computer's screen. For your phone, press Show the code there, above your threads."
      : `Done. Turn on this computer's agents in Harness on your other computer. For your phone: ${relayCommand()} phone pair`
  );
}

