// Harness inside Herdr: your swarm's threads beside your agents. Each thread says who works, what it is on, and what
// waits on you; clicking one goes to its Herdr space, where its agents' turns run. Asking here starts a thread in the
// focused terminal's folder. Everything comes from `tryharness herdr` (Harness's CLI), so the panel holds no logic.
import { View, div, svg } from "gpui-kit";
import { v_flex, h_flex, InputState, Input } from "gpui-base";
import { exec, focused, nextCommand, notify, run, spaces, theme } from "herdr";

// Threads change at the speed of agents' turns: a read every few seconds is enough, and costs one CLI call.
const READ_EVERY_MS = 4000;

/** Where a thread asked here works: the focused terminal's folder, else the shown space's (the panel itself focused). */
const askFolder = () =>
  focused()?.cwd || spaces().find((space) => space.active)?.folder || null;

const order = (a, b) =>
  b.needsYou - a.needsYou ||
  b.working.length - a.working.length ||
  String(b.at ?? "").localeCompare(String(a.at ?? ""));

export default class Harness extends View {
  init(_props, cx) {
    this.threads = [];
    this.problem = null;
    this.sending = false;
    this.needs = new Map();
    this.showing = new Set();
    this.posts = new Map();
    this.input = InputState.new({ placeholder: "Ask your swarm…" });
    this.input.on("submit", (_e, cx) => this.ask(cx));
    this.replyTo = null;
    cx.timer.every(READ_EVERY_MS, (cx) => this.read(cx));
    this.read(cx);
    // Its commands, for keys bound in Herdr's keys.json ("harness.next", "harness.ask") or `herdr-app do harness.next`.
    cx.spawn(async (cx) => {
      for (;;) {
        const command = await nextCommand();
        if (command === "next") this.next();
        if (command === "ask") this.input.focus();
        cx.notify();
      }
    });
  }

  replying() {
    return this.threads.find((thread) => thread.id === this.replyTo) ?? null;
  }

  /** To the space of the thread that most wants the person: waiting on them, else working, else the latest. */
  next() {
    const shown = this.threads.find((thread) => thread.space);
    if (shown) this.open(shown);
  }

  read(cx) {
    cx.spawn(async (cx) => {
      try {
        const out = await exec("tryharness", ["herdr", "board"]);
        if (out.code !== 0)
          throw new Error(out.stderr.trim().split("\n").at(-1) || "no answer");
        this.threads = JSON.parse(out.stdout).threads.sort(order);
        for (const id of this.showing) this.readPosts(id, cx);
        this.problem = null;
        this.tell();
      } catch {
        // What failed is in Harness's own logs; here, what to do about it.
        this.problem =
          "Harness isn't running on this computer. Start it with: npx tryharness";
      }
      cx.notify();
    });
  }

  /** A thread that starts waiting on you says so once, with a way to its space. */
  tell() {
    for (const thread of this.threads) {
      const before = this.needs.get(thread.id) ?? 0;
      if (thread.needsYou > before)
        notify({
          title: `${thread.title} needs you`,
          body: thread.line ?? undefined,
          level: "warning",
          ...(thread.space
            ? { action: { name: "space.select", args: { id: thread.space } } }
            : {}),
        });
      this.needs.set(thread.id, thread.needsYou);
    }
  }

  /** Enter: into the thread being replied to, else a new thread in the shown folder. */
  ask(cx) {
    const text = this.input.value().trim();
    if (!text || this.sending) return;
    const reply = this.threads.find((thread) => thread.id === this.replyTo);
    const folder = askFolder();
    if (!reply && !folder) {
      this.problem =
        "Open a space in the folder the thread should work in, then ask.";
      return cx.notify();
    }
    this.sending = true;
    cx.notify();
    const args = reply
      ? ["herdr", "post", reply.id, text]
      : ["herdr", "start", folder, text];
    cx.spawn(async (cx) => {
      const out = await exec("tryharness", args).catch((error) => ({
        code: 1,
        stderr: String(error.message ?? error),
      }));
      this.sending = false;
      if (out.code === 0) this.input.set_value("");
      else
        this.problem = `Harness didn't take it: ${out.stderr.trim().split("\n").at(-1)}`;
      this.read(cx);
    });
  }

  /** A thread clicked: its space shown, and what is typed next goes into it. */
  open(thread) {
    this.replyTo = thread.id;
    if (thread.space) run("space.select", { id: thread.space });
    else exec("tryharness", ["desktop"]).catch(() => null);
  }

  mark(thread, t) {
    if (thread.needsYou)
      return div()
        .flex_none()
        .px(6)
        .h(18)
        .rounded(5)
        .bg(t.blocked + "26")
        .text_size(10.5)
        .font_semibold()
        .text_color(t.blocked)
        .flex()
        .items_center()
        .child("Needs you");
    if (thread.working.length)
      return svg("mods/workspace-chrome/spinner.svg")
        .size(12)
        .mx(1)
        .flex_none()
        .text_color(t.working)
        .spin(900);
    return div()
      .size(7)
      .mx(3)
      .flex_none()
      .rounded(4)
      .border(1.5)
      .border_color(t.idle ?? t.dim);
  }

  render() {
    const t = theme();
    const rows = this.threads.map((thread) =>
      v_flex().child(this.row(thread, t)).child(this.shown(thread, t))
    );
    return this.frame(rows, t);
  }

  /** A thread's line: click to go to its space and reply into it. */
  row(thread, t) {
    return v_flex()
      .id(`hs-${thread.id}`)
      .gap(2)
      .px(10)
      .py(7)
      .rounded(7)
      .cursor_pointer()
      .hover((s) => s.bg(t.hover ?? t.raised))
      .on_click(() => this.open(thread))
      .child(
        h_flex()
          .gap(7)
          .items_center()
          .child(this.mark(thread, t))
          .child(
            div()
              .flex_1()
              .min_w(0)
              .truncate()
              .text_size(12.5)
              .text_color(t.foreground)
              .child(thread.title)
          )
      )
      .when(Boolean(thread.line), (el) =>
        el.child(
          div()
            .pl(20)
            .truncate()
            .text_size(11.5)
            .text_color(t.muted)
            .child(thread.line)
        )
      )
      .when(thread.working.length > 0, (el) =>
        el.child(
          div()
            .pl(20)
            .truncate()
            .text_size(11)
            .text_color(t.dim)
            .child(`${thread.working.join(", ")} working`)
        )
      );
  }

  /** Under a thread: its latest posts when shown, read through tryharness herdr read. */
  shown(thread, t) {
    const open = this.showing.has(thread.id);
    const posts = this.posts.get(thread.id) ?? [];
    return v_flex()
      .pl(30)
      .pr(10)
      .pb(6)
      .gap(4)
      .child(
        div()
          .id(`hs-show-${thread.id}`)
          .text_size(11)
          .text_color(t.accent)
          .cursor_pointer()
          .on_click((_e, cx) => this.toggle(thread, cx))
          .child(open ? "Hide posts" : "Show latest posts")
      )
      .when(open, (el) =>
        el.children(
          posts.map((post, index) =>
            v_flex()
              .id(`hs-post-${thread.id}-${index}`)
              .gap(1)
              .child(div().text_size(11).text_color(t.dim).child(post.by))
              .child(
                div().text_size(12).text_color(t.foreground).child(post.text)
              )
          )
        )
      );
  }

  toggle(thread, cx) {
    if (this.showing.has(thread.id)) this.showing.delete(thread.id);
    else {
      this.showing.add(thread.id);
      this.readPosts(thread.id, cx);
    }
    cx.notify();
  }

  /** A shown thread's posts, read again with the board. */
  readPosts(id, cx) {
    cx.spawn(async (cx) => {
      const out = await exec("tryharness", ["herdr", "read", id]).catch(
        () => null
      );
      try {
        if (out?.code === 0) this.posts.set(id, JSON.parse(out.stdout).posts);
      } catch {}
      cx.notify();
    });
  }

  frame(rows, t) {
    return v_flex()
      .id("harness")
      .size_full()
      .min_h(0)
      .bg(t.chrome ?? t.surface)
      .text_color(t.foreground)
      .child(
        h_flex()
          .px(12)
          .pt(12)
          .pb(8)
          .items_center()
          .child(div().flex_1().text_size(13).font_semibold().child("Harness"))
          .child(
            div()
              .text_size(11)
              .text_color(t.dim)
              .child(
                `${this.threads.length} ${this.threads.length === 1 ? "thread" : "threads"}`
              )
          )
      )
      .child(
        div()
          .px(10)
          .pb(8)
          .child(
            Input.new(this.input)
              .h(32)
              .px(9)
              .rounded(8)
              .border_1()
              .border_color(t.input)
              .bg(t.background)
              .text_size(12.5)
              .text_color(t.foreground)
          )
      )
      .child(
        div()
          .px(12)
          .pb(6)
          .text_size(11)
          .text_color(t.dim)
          .child(
            this.sending
              ? "Sending…"
              : this.replying()
                ? `Enter posts to ${this.replying().title}.`
                : `Enter starts a thread in ${askFolder() ?? "this space's folder"}.`
          )
      )
      .when(Boolean(this.replying()) && !this.sending, (el) =>
        el.child(
          div()
            .id("hs-new-thread")
            .px(12)
            .pb(8)
            .text_size(11)
            .text_color(t.accent)
            .cursor_pointer()
            .on_click((_e, cx) => {
              this.replyTo = null;
              cx.notify();
            })
            .child("Start a new thread instead")
        )
      )
      .when(Boolean(this.problem), (el) =>
        el.child(
          div()
            .px(12)
            .pb(8)
            .text_size(11.5)
            .text_color(t.blocked)
            .child(this.problem)
        )
      )
      .when(!this.problem && this.threads.length === 0, (el) =>
        el.child(
          div()
            .px(12)
            .text_size(12)
            .text_color(t.dim)
            .child(
              "No threads yet. Ask above, and your agents take it from there."
            )
        )
      )
      .child(
        v_flex()
          .id("hs-list")
          .flex_1()
          .min_h(0)
          .px(4)
          .overflow_y_scrollbar()
          .children(rows)
      );
  }
}
